20	  | {
21	    readonly id: string;
22	    readonly op: "hash-password";
23	    readonly password: Uint8Array;
24	    readonly salt: Uint8Array;
25	    readonly memoryCostKiB: number;
26	    readonly timeCost: number;
27	    readonly parallelism: number;
28	    readonly hashLength: number;
29	  }
30	  | {
31	    readonly id: string;
32	    readonly op: "verify-password";
33	    readonly password: Uint8Array;
34	    readonly encodedHash: string;
35	  }
36	  | {
37	    readonly id: string;
38	    readonly op: "hash-audit";
39	    readonly value: Uint8Array;
40	    readonly salt: Uint8Array;
41	    readonly memoryCostKiB: number;
42	    readonly iterations: number;
43	    readonly parallelism: number;
44	    readonly hashLength: number;
45	  };
