47	export type Argon2WorkerResponse =
48	  | { readonly kind: "ready" }
49	  | { readonly kind: "result"; readonly id: string; readonly digest: string }
50	  | { readonly kind: "verified"; readonly id: string; readonly matches: boolean }
51	  | { readonly kind: "failed"; readonly id: string; readonly code: string };
