71	 * but the worker still refuses anything it cannot interpret exactly rather than
72	 * coercing it into an Argon2 call with attacker-influenced parameters.
73	 */
74	export function isArgon2WorkerRequest(value: unknown): value is Argon2WorkerRequest {
75	  if (typeof value !== "object" || value === null) return false;
76	  const candidate = value as Record<string, unknown>;
77	  if (typeof candidate.id !== "string" || candidate.id.length === 0) return false;
78	  if (candidate.op === "hash-password") {
79	    return isBytes(candidate.password) && isBytes(candidate.salt)
80	      && isPositiveInteger(candidate.memoryCostKiB) && isPositiveInteger(candidate.timeCost)
81	      && isPositiveInteger(candidate.parallelism) && isPositiveInteger(candidate.hashLength);
82	  }
83	  if (candidate.op === "verify-password") {
84	    return isBytes(candidate.password) && typeof candidate.encodedHash === "string";
85	  }
86	  if (candidate.op === "hash-audit") {
87	    return isBytes(candidate.value) && isBytes(candidate.salt)
88	      && isPositiveInteger(candidate.memoryCostKiB) && isPositiveInteger(candidate.iterations)
89	      && isPositiveInteger(candidate.parallelism) && isPositiveInteger(candidate.hashLength);
