94	/**
95	 * Executes one validated request. Exported for direct unit testing without a
96	 * live thread; the message handler below is a thin adapter over it.
97	 */
98	export async function executeArgon2WorkerRequest(
99	  request: Argon2WorkerRequest
100	): Promise<Argon2WorkerResponse> {
101	  try {
102	    if (request.op === "hash-password") {
103	      try {
104	        const digest = await argon2id({
105	          password: request.password,
106	          salt: request.salt,
107	          memorySize: request.memoryCostKiB,
108	          iterations: request.timeCost,
109	          parallelism: request.parallelism,
110	          hashLength: request.hashLength,
111	          outputType: "encoded"
112	        });
113	        return { kind: "result", id: request.id, digest };
114	      } finally {
115	        zero(request.password);
116	        zero(request.salt);
117	      }
118	    }
119	    if (request.op === "verify-password") {
120	      try {
121	        // Mirrors the pre-existing `catch { return false }` contract exactly: a
122	        // wrong password, or an encoded hash argon2Verify cannot parse, is a
123	        // normal negative verification, not an infrastructure fault.
124	        //
125	        // This is NOT the prohibited "failure becomes false" path. The failures
126	        // the pool must never convert to `false` — worker crash, job timeout,
127	        // lane/total capacity exhaustion, closed pool — are detected by the
128	        // parent, which never receives a `verified` message for them.
129	        let matches = false;
130	        try {
131	          matches = await argon2Verify({
132	            password: request.password,
133	            hash: request.encodedHash
134	          });
135	        } catch {
136	          matches = false;
137	        }
138	        return { kind: "verified", id: request.id, matches };
139	      } finally {
140	        zero(request.password);
141	      }
142	    }
143	    try {
144	      const digest = await argon2id({
145	        password: request.value,
146	        salt: request.salt,
147	        memorySize: request.memoryCostKiB,
148	        iterations: request.iterations,
149	        parallelism: request.parallelism,
150	        hashLength: request.hashLength,
151	        outputType: "hex"
152	      });
153	      return { kind: "result", id: request.id, digest };
154	    } finally {
155	      zero(request.value);
156	      zero(request.salt);
157	    }
158	  } catch {
159	    // Deliberately discards the caught value: hash-wasm error text can echo
160	    // input-derived detail, and this message crosses a thread boundary.
161	    return { kind: "failed", id: request.id, code: ARGON2_WORKER_JOB_FAILED };
