1	// Bounded, process-owned Argon2 worker pool.
2	//
3	// Owns every off-thread Argon2 compute: worker spawn and readiness, the two
4	// bounded lanes, protocol validation, job timeouts, crash handling, the restart
5	// breaker, and the close contract. It never imports hash-wasm — only
6	// ./argon2-worker.ts does, and only inside the worker thread.
7	//
8	// PLAINTEXT OWNERSHIP. A secret-bearing payload has exactly one live owner at
9	// any moment:
10	//   1. caller -> `QueuedJob.request` at enqueue (the queue node owns it);
11	//   2. queue node -> worker thread at dispatch, via structured-clone transfer,
12	//      which detaches the parent's buffers and `request` is cleared in the same
13	//      step (the worker owns it, and zeroes it in its own `finally`);
14	//   3. on cancel/capacity-reject/close before dispatch, the queue node zeroes
15	//      the bytes and clears the reference (nobody owns it).
16	// A payload is therefore never reachable from two queue nodes at once, and is
17	// never retained after settlement.
18	
19	import { randomBytes } from "node:crypto";
20	import { Worker } from "node:worker_threads";
21	import type { Argon2WorkerRequest, Argon2WorkerResponse } from "./argon2-worker.js";
22	
23	export type Argon2FailureCode =
24	  | "ARGON2_POOL_CAPACITY_EXHAUSTED"
25	  | "ARGON2_POOL_UNAVAILABLE"
26	  | "ARGON2_WORKER_FAILED"
27	  | "ARGON2_JOB_TIMEOUT";
28	
29	/**
30	 * The only failure type callers see. Constant, secret-free, and never
31	 * convertible into `false` or a weaker hash by any path in this module.
32	 */
33	export class Argon2InfrastructureError extends Error {
34	  readonly code: Argon2FailureCode;
35	  readonly retryable: boolean;
36	
37	  constructor(code: Argon2FailureCode) {
38	    super(code);
39	    this.name = "Argon2InfrastructureError";
40	    this.code = code;
41	    // Capacity exhaustion is transient back-pressure; a dead or closed pool is
42	    // not something the same request should hammer.
43	    this.retryable = code === "ARGON2_POOL_CAPACITY_EXHAUSTED";
44	  }
45	}
46	
47	export type Argon2Lane = "credential" | "audit";
48	
49	/**
50	 * PROVISIONAL engineering bounds — candidate values only.
51	 *
52	 * These are NOT ruled auth policy and are deliberately not persisted as a
53	 * register row: changing an already-sealed deployed register version would
54	 * require a wider migration/version decision that this ticket does not own.
55	 * They are named, typed construction bounds adjacent to the pool; tests inject
56	 * smaller values. Router must obtain V's explicit ratification against measured
57	 * RSS evidence before final custody.
58	 *
59	 * `workers: 2` is deliberate: the frozen logical
60	 * `maxConcurrentRegistrationHashes = 32` is an admission-policy value, not a
61	 * thread count. 32 physical workers at 64 MiB would risk an ~2 GiB Argon
62	 * allocation.
63	 */
64	export const ARGON2_PROVISIONAL_BOUNDS = Object.freeze({
65	  workers: 2,
66	  credentialLaneCap: 32,
67	  auditLaneCap: 96,
68	  totalCap: 128,
69	  jobTimeoutMs: 10_000,
70	  restartBudget: 3,
71	  restartWindowMs: 60_000,
72	  closeDrainMs: 5_000
73	});
74	
75	/** Minimal surface the pool needs, so tests can inject barrier/fault fixtures. */
76	export interface Argon2WorkerHandle {
77	  readonly threadId: number;
78	  postMessage(message: unknown, transfer?: readonly ArrayBuffer[]): void;
79	  on(event: "message", listener: (value: unknown) => void): void;
80	  on(event: "error", listener: (error: unknown) => void): void;
81	  on(event: "exit", listener: (code: number) => void): void;
82	  terminate(): Promise<unknown>;
83	  ref(): void;
84	  unref(): void;
85	}
86	
87	export interface Argon2WorkerPoolOptions {
88	  readonly workers?: number;
89	  readonly credentialLaneCap?: number;
90	  readonly auditLaneCap?: number;
91	  readonly totalCap?: number;
92	  readonly jobTimeoutMs?: number;
93	  readonly restartBudget?: number;
94	  readonly restartWindowMs?: number;
95	  readonly closeDrainMs?: number;
96	  readonly spawn?: (index: number) => Argon2WorkerHandle;
97	  readonly now?: () => number;
98	}
99	
100	export interface Argon2PoolStats {
101	  readonly state: "OPEN" | "CLOSING" | "CLOSED";
102	  readonly workers: number;
103	  readonly readyWorkers: number;
104	  readonly active: number;
105	  readonly queuedCredential: number;
106	  readonly queuedAudit: number;
107	  readonly queuedTotal: number;
108	  readonly outstandingCredential: number;
109	  readonly outstandingAudit: number;
110	  readonly outstandingTotal: number;
111	  readonly restartsInWindow: number;
112	  readonly breakerTripped: boolean;
113	}
114	
115	export interface Argon2PasswordParameters {
116	  readonly memoryCostKiB: number;
117	  readonly timeCost: number;
118	  readonly parallelism: number;
119	  readonly hashLength: number;
120	}
121	
122	export interface Argon2AuditParameters {
123	  readonly memoryCostKiB: number;
124	  readonly iterations: number;
125	  readonly parallelism: number;
126	  readonly hashLength: number;
127	}
128	
129	interface QueuedJob {
130	  readonly id: string;
131	  readonly lane: Argon2Lane;
132	  /** Single live owner of the plaintext until dispatch; cleared at handoff. */
133	  request: Argon2WorkerRequest | undefined;
134	  readonly resolve: (value: string | boolean) => void;
135	  readonly reject: (error: unknown) => void;
136	  settled: boolean;
137	}
138	
139	interface ActiveJob {
140	  readonly job: QueuedJob;
141	  timer: ReturnType<typeof setTimeout> | undefined;
142	}
143	
144	interface Slot {
145	  readonly index: number;
146	  handle: Argon2WorkerHandle | undefined;
147	  ready: boolean;
148	  active: ActiveJob | undefined;
149	  /** Bumped on every replacement so late events from a dead worker are ignored. */
150	  generation: number;
151	}
152	
153	/**
154	 * The transferable buffers backing a request's secret bytes. Only views that
155	 * exactly cover their own ArrayBuffer are transferred: `Buffer.from(string)`
156	 * draws from Node's shared 8 KiB allocation pool, and transferring that shared
157	 * ArrayBuffer would detach unrelated live Buffers.
158	 */
159	function collectTransferables(request: Argon2WorkerRequest): ArrayBuffer[] {
160	  const views: Uint8Array[] = [];
161	  if (request.op === "hash-password") views.push(request.password, request.salt);
162	  else if (request.op === "verify-password") views.push(request.password);
163	  else views.push(request.value, request.salt);
164	  const buffers: ArrayBuffer[] = [];
165	  for (const view of views) {
166	    if (view.byteOffset === 0 && view.byteLength === view.buffer.byteLength
167	      && view.buffer instanceof ArrayBuffer && !buffers.includes(view.buffer)) {
168	      buffers.push(view.buffer);
169	    }
170	  }
171	  return buffers;
172	}
173	
174	function zeroRequest(request: Argon2WorkerRequest | undefined): void {
175	  if (request === undefined) return;
176	  if (request.op === "hash-password") {
177	    request.password.fill(0);
178	    request.salt.fill(0);
179	  } else if (request.op === "verify-password") {
180	    request.password.fill(0);
181	  } else {
182	    request.value.fill(0);
183	    request.salt.fill(0);
184	  }
185	}
186	
187	function isResponse(value: unknown): value is Argon2WorkerResponse {
188	  if (typeof value !== "object" || value === null) return false;
189	  const candidate = value as Record<string, unknown>;
190	  if (candidate.kind === "ready") return true;
191	  if (typeof candidate.id !== "string") return false;
192	  if (candidate.kind === "result") return typeof candidate.digest === "string";
193	  if (candidate.kind === "verified") return typeof candidate.matches === "boolean";
194	  if (candidate.kind === "failed") return typeof candidate.code === "string";
195	  return false;
196	}
197	
198	export class Argon2WorkerPool {
199	  private readonly workerCount: number;
200	  private readonly credentialLaneCap: number;
201	  private readonly auditLaneCap: number;
202	  private readonly totalCap: number;
203	  private readonly jobTimeoutMs: number;
204	  private readonly restartBudget: number;
205	  private readonly restartWindowMs: number;
206	  private readonly closeDrainMs: number;
207	  private readonly spawnWorker: (index: number) => Argon2WorkerHandle;
208	  private readonly now: () => number;
209	
210	  private readonly slots: Slot[] = [];
211	  private readonly queues: Record<Argon2Lane, QueuedJob[]> = { credential: [], audit: [] };
212	  private nextLane: Argon2Lane = "credential";
213	  private state: "OPEN" | "CLOSING" | "CLOSED" = "OPEN";
214	  private breakerTripped = false;
215	  private restarts: number[] = [];
216	  private readyPromise: Promise<void> | undefined;
217	  private readyWaiters: { resolve: () => void; reject: (error: unknown) => void }[] = [];
218	  private closePromise: Promise<void> | undefined;
219	
220	  constructor(options: Argon2WorkerPoolOptions = {}) {
221	    this.workerCount = options.workers ?? ARGON2_PROVISIONAL_BOUNDS.workers;
222	    this.credentialLaneCap = options.credentialLaneCap ?? ARGON2_PROVISIONAL_BOUNDS.credentialLaneCap;
223	    this.auditLaneCap = options.auditLaneCap ?? ARGON2_PROVISIONAL_BOUNDS.auditLaneCap;
224	    this.totalCap = options.totalCap ?? ARGON2_PROVISIONAL_BOUNDS.totalCap;
225	    this.jobTimeoutMs = options.jobTimeoutMs ?? ARGON2_PROVISIONAL_BOUNDS.jobTimeoutMs;
226	    this.restartBudget = options.restartBudget ?? ARGON2_PROVISIONAL_BOUNDS.restartBudget;
227	    this.restartWindowMs = options.restartWindowMs ?? ARGON2_PROVISIONAL_BOUNDS.restartWindowMs;
228	    this.closeDrainMs = options.closeDrainMs ?? ARGON2_PROVISIONAL_BOUNDS.closeDrainMs;
229	    this.now = options.now ?? Date.now;
230	    this.spawnWorker = options.spawn ?? ((index) => Argon2WorkerPool.spawnRealWorker(index));
231	    if (!Number.isInteger(this.workerCount) || this.workerCount < 1) {
232	      throw new TypeError("ARGON2_POOL_WORKER_COUNT_INVALID");
233	    }
234	    if (this.credentialLaneCap < 1 || this.auditLaneCap < 1 || this.totalCap < 1) {
235	      throw new TypeError("ARGON2_POOL_CAPACITY_INVALID");
236	    }
237	    for (let index = 0; index < this.workerCount; index += 1) {
238	      const slot: Slot = { index, handle: undefined, ready: false, active: undefined, generation: 0 };
239	      this.slots.push(slot);
240	      this.startSlot(slot);
241	    }
242	  }
243	
244	  /**
245	   * Spawns the real worker from its own module URL with an explicitly empty
246	   * `execArgv`. The empty array is load-bearing: inheriting the parent's flags
247	   * would make the worker depend on a tsx/Vitest loader that plain `node` does
248	   * not have, so the process would boot in tests and fail in production.
249	   */
250	  private static spawnRealWorker(index: number): Argon2WorkerHandle {
251	    return new Worker(new URL("./argon2-worker.ts", import.meta.url), {
252	      execArgv: [],
253	      name: `argon2-worker-${index}`
254	    }) as unknown as Argon2WorkerHandle;
255	  }
256	
257	  private startSlot(slot: Slot): void {
258	    const generation = slot.generation;
259	    let handle: Argon2WorkerHandle;
260	    try {
261	      handle = this.spawnWorker(slot.index);
262	    } catch {
263	      this.recordFailure();
264	      return;
265	    }
266	    slot.handle = handle;
267	    slot.ready = false;
268	    handle.on("message", (value: unknown) => {
269	      if (slot.generation !== generation) return;
270	      this.onMessage(slot, value);
271	    });
272	    handle.on("error", () => {
273	      if (slot.generation !== generation) return;
274	      this.onWorkerLost(slot);
275	    });
276	    handle.on("exit", () => {
277	      if (slot.generation !== generation) return;
278	      this.onWorkerLost(slot);
279	    });
280	    // Deliberately left ref'd until the ready handshake lands: a booting worker
281	    // MUST hold the process open, or an otherwise-idle process can exit while
282	    // `ready()` is still pending. It is unref'd in `onMessage` once ready, and
283	    // re-ref'd only while it owns an in-flight job.
284	    //
285	    // (Order also matters for the unref itself: attaching a "message" listener
286	    // re-refs the underlying port, so unref'ing before registration is silently
287	    // undone.)
288	  }
289	
290	  /** An idle, ready worker must not hold a terminating process open. */
291	  private unrefIfIdle(slot: Slot): void {
292	    if (slot.active === undefined) slot.handle?.unref();
293	  }
294	
295	  /**
296	   * Resolves once every worker has completed its ready handshake.
297	   *
298	   * Event-driven on purpose. A polling loop would have to hold an unref'd timer
299	   * (a ref'd one would keep an idle process alive), and once the last worker
300	   * became ready and unref'd itself nothing would remain to keep the loop
301	   * turning — the poll would never fire and this promise would never settle.
302	   */
303	  ready(): Promise<void> {
304	    if (this.readyPromise === undefined) {
305	      this.readyPromise = new Promise<void>((resolve, reject) => {
306	        this.readyWaiters.push({ resolve, reject });
307	      });
308	      this.settleReady();
309	    }
310	    return this.readyPromise;
311	  }
312	
313	  /**
314	   * Resolves waiters as soon as every slot is ready. Called BEFORE workers are
315	   * unref'd, so the continuation is already queued as a microtask and cannot be
316	   * lost to an early exit.
317	   */
318	  private settleReady(): void {
319	    if (this.readyWaiters.length === 0) return;
320	    if (this.state !== "OPEN" || this.breakerTripped) {
321	      const waiters = this.readyWaiters;
322	      this.readyWaiters = [];
323	      for (const waiter of waiters) {
324	        waiter.reject(new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
325	      }
326	      return;
327	    }
328	    if (!this.slots.every((slot) => slot.ready)) return;
329	    const waiters = this.readyWaiters;
330	    this.readyWaiters = [];
331	    for (const waiter of waiters) waiter.resolve();
332	  }
333	
334	  stats(): Argon2PoolStats {
335	    const active = this.slots.filter((slot) => slot.active !== undefined).length;
336	    const activeCredential = this.slots.filter(
337	      (slot) => slot.active?.job.lane === "credential"
338	    ).length;
339	    const activeAudit = active - activeCredential;
340	    return Object.freeze({
341	      state: this.state,
342	      workers: this.slots.length,
343	      readyWorkers: this.slots.filter((slot) => slot.ready).length,
344	      active,
345	      queuedCredential: this.queues.credential.length,
346	      queuedAudit: this.queues.audit.length,
347	      queuedTotal: this.queues.credential.length + this.queues.audit.length,
348	      outstandingCredential: this.queues.credential.length + activeCredential,
349	      outstandingAudit: this.queues.audit.length + activeAudit,
350	      outstandingTotal: this.queues.credential.length + this.queues.audit.length + active,
351	      restartsInWindow: this.restarts.length,
352	      breakerTripped: this.breakerTripped
353	    });
354	  }
355	
356	  // ------------------------------------------------------------- public API --
357	
358	  async hashPassword(
359	    password: Uint8Array,
360	    salt: Uint8Array,
361	    parameters: Argon2PasswordParameters
362	  ): Promise<string> {
363	    const id = Argon2WorkerPool.newJobId();
364	    const result = await this.submit("credential", {
365	      id,
366	      op: "hash-password",
367	      password,
368	      salt,
369	      memoryCostKiB: parameters.memoryCostKiB,
370	      timeCost: parameters.timeCost,
371	      parallelism: parameters.parallelism,
372	      hashLength: parameters.hashLength
373	    });
374	    if (typeof result !== "string") throw new Argon2InfrastructureError("ARGON2_WORKER_FAILED");
375	    return result;
376	  }
377	
378	  async verifyPassword(password: Uint8Array, encodedHash: string): Promise<boolean> {
379	    const id = Argon2WorkerPool.newJobId();
380	    const result = await this.submit("credential", {
381	      id,
382	      op: "verify-password",
383	      password,
384	      encodedHash
385	    });
386	    if (typeof result !== "boolean") throw new Argon2InfrastructureError("ARGON2_WORKER_FAILED");
387	    return result;
388	  }
389	
390	  async hashAuditContext(
391	    value: Uint8Array,
392	    salt: Uint8Array,
393	    parameters: Argon2AuditParameters
394	  ): Promise<string> {
395	    const id = Argon2WorkerPool.newJobId();
396	    const result = await this.submit("audit", {
397	      id,
398	      op: "hash-audit",
399	      value,
400	      salt,
401	      memoryCostKiB: parameters.memoryCostKiB,
402	      iterations: parameters.iterations,
403	      parallelism: parameters.parallelism,
404	      hashLength: parameters.hashLength
405	    });
406	    if (typeof result !== "string") throw new Argon2InfrastructureError("ARGON2_WORKER_FAILED");
407	    return result;
408	  }
409	
410	  /** Unpredictable, so a message cannot be forged or correlated by position. */
411	  private static newJobId(): string {
412	    return randomBytes(16).toString("hex");
413	  }
414	
415	  private laneCap(lane: Argon2Lane): number {
416	    return lane === "credential" ? this.credentialLaneCap : this.auditLaneCap;
417	  }
418	
419	  private outstanding(lane: Argon2Lane): number {
420	    const stats = this.stats();
421	    return lane === "credential" ? stats.outstandingCredential : stats.outstandingAudit;
422	  }
423	
424	  private submit(lane: Argon2Lane, request: Argon2WorkerRequest): Promise<string | boolean> {
425	    // Capacity and liveness are decided BEFORE the payload is retained anywhere.
426	    // On refusal the caller's bytes are zeroed and never enter a queue node.
427	    if (this.state !== "OPEN" || this.breakerTripped) {
428	      zeroRequest(request);
429	      return Promise.reject(new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
430	    }
431	    if (this.outstanding(lane) >= this.laneCap(lane)
432	      || this.stats().outstandingTotal >= this.totalCap) {
433	      zeroRequest(request);
434	      return Promise.reject(new Argon2InfrastructureError("ARGON2_POOL_CAPACITY_EXHAUSTED"));
435	    }
436	    return new Promise<string | boolean>((resolve, reject) => {
437	      const job: QueuedJob = { id: request.id, lane, request, resolve, reject, settled: false };
438	      this.queues[lane].push(job);
439	      this.pump();
440	    });
441	  }
442	
443	  // ------------------------------------------------------------- scheduling --
444	
445	  /**
446	   * Strict alternation between lanes whenever both are backlogged. This is the
447	   * starvation bound: a registration burst can delay an audit by at most one
448	   * dispatch per idle worker, and audit traffic can delay credentials likewise.
449	   */
450	  private takeNextJob(): QueuedJob | undefined {
451	    const order: Argon2Lane[] = this.nextLane === "credential"
452	      ? ["credential", "audit"]
453	      : ["audit", "credential"];
454	    for (const lane of order) {
455	      const queue = this.queues[lane];
456	      const job = queue.shift();
457	      if (job !== undefined) {
458	        this.nextLane = lane === "credential" ? "audit" : "credential";
459	        return job;
460	      }
461	    }
462	    return undefined;
463	  }
464	
465	  private pump(): void {
466	    if (this.state === "CLOSED" || this.breakerTripped) return;
467	    for (const slot of this.slots) {
468	      // One in-flight job per worker.
469	      if (slot.active !== undefined || !slot.ready || slot.handle === undefined) continue;
470	      const job = this.takeNextJob();
471	      if (job === undefined) return;
472	      this.dispatch(slot, job);
473	    }
474	  }
475	
476	  private dispatch(slot: Slot, job: QueuedJob): void {
477	    const request = job.request;
478	    if (request === undefined) return;
479	    const handle = slot.handle;
480	    if (handle === undefined) {
481	      this.queues[job.lane].unshift(job);
482	      return;
483	    }
484	    const active: ActiveJob = { job, timer: undefined };
485	    slot.active = active;
486	    handle.ref();
487	    try {
488	      handle.postMessage(request, collectTransferables(request));
489	    } catch {
490	      slot.active = undefined;
491	      handle.unref();
492	      zeroRequest(request);
493	      job.request = undefined;
494	      this.settle(job, new Argon2InfrastructureError("ARGON2_WORKER_FAILED"));
495	      this.onWorkerLost(slot);
496	      return;
497	    }
498	    // Ownership has moved to the worker thread; the parent's views are now
499	    // detached. Drop the reference so no queue node still points at the payload.
500	    job.request = undefined;
501	    // Timeout is measured from DISPATCH, not enqueue, so queue latency under
502	    // back-pressure can never manufacture a spurious timeout.
503	    active.timer = setTimeout(() => {
504	      if (slot.active !== active) return;
505	      this.finishActive(slot);
506	      this.settle(job, new Argon2InfrastructureError("ARGON2_JOB_TIMEOUT"));
507	      // The job is NOT retried: it carried a secret and has been settled once.
508	      // The worker is replaced only so later queued work has capacity.
509	      this.replaceSlot(slot);
510	    }, this.jobTimeoutMs);
511	    active.timer.unref?.();
512	  }
513	
514	  private finishActive(slot: Slot): void {
515	    const active = slot.active;
516	    if (active === undefined) return;
517	    if (active.timer !== undefined) clearTimeout(active.timer);
518	    slot.active = undefined;
519	    slot.handle?.unref();
520	  }
521	
522	  private settle(job: QueuedJob, error: unknown, value?: string | boolean): void {
523	    // Exactly-once settlement for every terminal path: result, protocol failure,
524	    // timeout, crash, breaker trip and close.
525	    if (job.settled) return;
526	    job.settled = true;
527	    zeroRequest(job.request);
528	    job.request = undefined;
529	    if (error !== undefined) job.reject(error);
530	    else job.resolve(value as string | boolean);
531	  }
532	
533	  // ----------------------------------------------------------------- events --
534	
535	  private onMessage(slot: Slot, value: unknown): void {
536	    if (!isResponse(value)) {
537	      // An uninterpretable frame means the protocol is not trustworthy on this
538	      // worker; treat it as a lost worker rather than guessing.
539	      this.onWorkerLost(slot);
540	      return;
541	    }
542	    if (value.kind === "ready") {
543	      slot.ready = true;
544	      this.settleReady();
545	      this.pump();
546	      // If pump() gave this slot a job it is now ref'd and must stay that way.
547	      this.unrefIfIdle(slot);
548	      return;
549	    }
550	    const active = slot.active;
551	    if (active === undefined || active.job.id !== value.id) return;
552	    this.finishActive(slot);
553	    if (value.kind === "result") this.settle(active.job, undefined, value.digest);
554	    else if (value.kind === "verified") this.settle(active.job, undefined, value.matches);
555	    else this.settle(active.job, new Argon2InfrastructureError("ARGON2_WORKER_FAILED"));
556	    this.pump();
557	  }
558	
559	  private onWorkerLost(slot: Slot): void {
560	    const active = slot.active;
561	    if (active !== undefined) {
562	      this.finishActive(slot);
563	      // Rejected exactly once, never retried: the payload is gone with the
564	      // worker and re-running it would need the secret back.
565	      this.settle(active.job, new Argon2InfrastructureError("ARGON2_WORKER_FAILED"));
566	    }
567	    slot.ready = false;
568	    this.replaceSlot(slot);
569	  }
570	
571	  private replaceSlot(slot: Slot): void {
572	    if (this.state !== "OPEN") return;
573	    slot.generation += 1;
574	    const dead = slot.handle;
575	    slot.handle = undefined;
576	    slot.ready = false;
577	    if (dead !== undefined) void Promise.resolve(dead.terminate()).catch(() => undefined);
578	    if (!this.recordFailure()) return;
579	    this.startSlot(slot);
580	    this.pump();
581	  }
582	
583	  /** Rolling restart budget. Returns false once the breaker has tripped. */
584	  private recordFailure(): boolean {
585	    const now = this.now();
586	    this.restarts = this.restarts.filter((at) => now - at < this.restartWindowMs);
587	    this.restarts.push(now);
588	    if (this.restarts.length > this.restartBudget) {
589	      this.tripBreaker();
590	      return false;
591	    }
592	    return true;
593	  }
594	
595	  /**
596	   * Fails the pool closed. Every queued and future promise settles with the
597	   * generic typed infrastructure error — never `false`, never a weaker hash.
598	   */
599	  private tripBreaker(): void {
600	    if (this.breakerTripped) return;
601	    this.breakerTripped = true;
602	    this.settleReady();
603	    this.rejectAllQueued(new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
604	    for (const slot of this.slots) {
605	      const active = slot.active;
606	      if (active !== undefined) {
607	        this.finishActive(slot);
608	        this.settle(active.job, new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
609	      }
610	      const handle = slot.handle;
611	      slot.handle = undefined;
612	      slot.ready = false;
613	      slot.generation += 1;
614	      if (handle !== undefined) void Promise.resolve(handle.terminate()).catch(() => undefined);
615	    }
616	  }
617	
618	  private rejectAllQueued(error: unknown): void {
619	    for (const lane of ["credential", "audit"] as const) {
620	      const queue = this.queues[lane];
621	      while (queue.length > 0) this.settle(queue.shift()!, error);
622	    }
623	  }
624	
625	  // ------------------------------------------------------------------ close --
626	
627	  /** Idempotent OPEN -> CLOSING -> CLOSED. Returns promptly and bounded. */
628	  close(): Promise<void> {
629	    this.closePromise ??= this.runClose();
630	    return this.closePromise;
631	  }
632	
633	  private async runClose(): Promise<void> {
634	    if (this.state === "CLOSED") return;
635	    this.state = "CLOSING";
636	    this.settleReady();
637	    // 1. New work is refused from this point (submit checks state !== OPEN).
638	    // 2. Drain in-flight work to a bounded deadline so a live KDF can finish.
639	    const deadline = this.now() + this.closeDrainMs;
640	    while (this.slots.some((slot) => slot.active !== undefined) && this.now() < deadline) {
641	      await new Promise<void>((resolve) => {
642	        const timer = setTimeout(resolve, 5);
643	        timer.unref?.();
644	      });
645	    }
646	    // 3. Anything still queued or still running is settled, exactly once.
647	    this.rejectAllQueued(new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
648	    for (const slot of this.slots) {
649	      const active = slot.active;
650	      if (active !== undefined) {
651	        this.finishActive(slot);
652	        this.settle(active.job, new Argon2InfrastructureError("ARGON2_POOL_UNAVAILABLE"));
653	      }
654	    }
655	    // 4. Terminate every worker.
656	    await Promise.all(this.slots.map(async (slot) => {
657	      const handle = slot.handle;
658	      slot.handle = undefined;
659	      slot.ready = false;
660	      slot.generation += 1;
661	      if (handle === undefined) return;
662	      try {
663	        await handle.terminate();
664	      } catch {
665	        // A worker that is already gone is an acceptable close outcome.
666	      }
667	    }));
668	    this.state = "CLOSED";
669	  }
670	}
