200	  try {
201	    if (typeof pathOrBuffer !== "string") return makeKekHandle(pathOrBuffer);
202	    const metadata = statSync(pathOrBuffer);
203	    if (!metadata.isFile() || (metadata.mode & 0o777) !== 0o600) {
204	      throw new KekUnresolvedError();
205	    }
206	    return makeKekHandle(readFileSync(pathOrBuffer));
207	  } catch (error) {
208	    if (error instanceof KekUnresolvedError) throw error;
209	    throw new KekUnresolvedError();
210	  }
211	}
