213	export function loadSecretKey(path: string): Buffer {
214	  try {
215	    const metadata = statSync(path);
216	    if (!metadata.isFile() || (metadata.mode & 0o777) !== 0o600) {
217	      throw new KekUnresolvedError();
218	    }
219	    return copyKey(readFileSync(path));
220	  } catch (error) {
221	    if (error instanceof KekUnresolvedError || error instanceof CryptoInputError) throw error;
222	    throw new KekUnresolvedError();
223	  }
224	}
