226	export function wrapDek(kek: KekHandle, dek: Uint8Array, aad: AeadAad): CryptoEnvelope {
227	  const key = readKek(kek);
228	  try {
229	    return encrypt(key, dek, aad);
230	  } finally {
231	    key.fill(0);
232	  }
233	}
