235	export function unwrapDek(kek: KekHandle, envelope: CryptoEnvelope, aad: AeadAad): Buffer {
236	  const key = readKek(kek);
237	  try {
238	    const dek = decrypt(key, envelope, aad);
239	    if (dek.byteLength !== KEY_BYTES) {
240	      dek.fill(0);
241	      throw new CryptoAuthenticationError();
242	    }
243	    return dek;
244	  } finally {
245	    key.fill(0);
246	  }
247	}
