249	export type AuditEventPayload = Readonly<Record<string, unknown>>;
250	
251	export type ChainedAuditEvent<T extends AuditEventPayload = AuditEventPayload> = Readonly<T & {
252	  readonly prevHash: string | null;
253	  readonly thisHash: string;
254	}>;
255	
256	function canonicalJson(value: unknown): string {
257	  if (value === null) return "null";
258	  if (typeof value === "string" || typeof value === "boolean") return JSON.stringify(value);
259	  if (typeof value === "number") {
260	    if (!Number.isFinite(value)) throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
261	    return JSON.stringify(value);
262	  }
263	  if (Buffer.isBuffer(value) || value instanceof Uint8Array) {
264	    return canonicalJson({ $bytes: Buffer.from(value).toString("base64") });
265	  }
266	  if (value instanceof Date) return JSON.stringify(value.toISOString());
267	  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item)).join(",")}]`;
268	  if (typeof value === "object") {
269	    const prototype = Object.getPrototypeOf(value);
270	    if (prototype !== Object.prototype && prototype !== null) {
271	      throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
272	    }
273	    const entries = Object.entries(value as Readonly<Record<string, unknown>>)
274	      .sort(([left], [right]) => left.localeCompare(right));
275	    return `{${entries.map(([key, item]) =>
276	      `${JSON.stringify(key)}:${canonicalJson(item)}`).join(",")}}`;
277	  }
278	  throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
279	}
280	
281	function validateAuditHash(hash: string): void {
282	  if (!/^[0-9a-f]{64}$/.test(hash)) {
283	    throw new CryptoInputError("CRYPTO_AUDIT_CHAIN_INVALID");
284	  }
285	}
286	
287	function auditHash(prevHash: string | null, payload: AuditEventPayload): string {
288	  if (prevHash !== null) validateAuditHash(prevHash);
289	  if (Object.hasOwn(payload, "prevHash") || Object.hasOwn(payload, "thisHash")) {
290	    throw new CryptoInputError("CRYPTO_AUDIT_CHAIN_INVALID");
291	  }
292	  const digest = createHash("sha256");
293	  if (prevHash !== null) digest.update(Buffer.from(prevHash, "hex"));
294	  digest.update(canonicalJson(payload), "utf8");
295	  return digest.digest("hex");
296	}
297	
298	/**
299	 * Appends one logical audit row with this_hash = H(prev_hash || canonical(payload)).
300	 * The payload deliberately excludes both hash columns; prev_hash comes solely
301	 * from the verified predecessor, so callers cannot construct a fork by accident.
302	 */
303	export function appendAuditEvent<T extends AuditEventPayload>(
304	  previous: ChainedAuditEvent | string | null,
305	  payload: T
306	): ChainedAuditEvent<T> {
307	  const prevHash = typeof previous === "string" ? previous : previous?.thisHash ?? null;
308	  const thisHash = auditHash(prevHash, payload);
309	  return Object.freeze({ ...payload, prevHash, thisHash });
310	}
311	
312	/**
313	 * Verifies genesis, every predecessor link, and every row digest. Supplying an
314	 * externally retained expected head additionally detects tail truncation.
315	 */
316	export function verifyChain(
317	  chain: readonly ChainedAuditEvent[],
318	  expectedHeadHash?: string
319	): boolean {
320	  try {
321	    let expectedPrev: string | null = null;
322	    for (const event of chain) {
323	      if (event.prevHash !== expectedPrev) return false;
324	      validateAuditHash(event.thisHash);
325	      const { prevHash: _prevHash, thisHash: _thisHash, ...payload } = event;
326	      if (auditHash(expectedPrev, payload) !== event.thisHash) return false;
327	      expectedPrev = event.thisHash;
328	    }
329	    if (expectedHeadHash !== undefined) {
330	      validateAuditHash(expectedHeadHash);
331	      return expectedPrev === expectedHeadHash;
332	    }
333	    return true;
334	  } catch {
335	    return false;
336	  }
337	}
