339	export function normalizeEmailForBlindIndex(email: string): string {
340	  const normalized = email.normalize("NFKC").trim().toLowerCase();
341	  if (normalized.length === 0 || !normalized.includes("@")) {
342	    throw new CryptoInputError("CRYPTO_EMAIL_INVALID");
343	  }
344	  return normalized;
345	}
346	
347	/**
348	 * Deterministic login lookup only. The key is global, separate from the KEK,
349	 * and independently rotatable. If an attacker compromises both the database
350	 * and this key, email's small domain permits offline enumeration; callers must
351	 * never treat the blind index as encryption or expose the key to the database.
352	 */
353	export function createEmailBlindIndex(key: Uint8Array, email: string): Buffer {
354	  const material = copyKey(key);
355	  try {
356	    return createHmac("sha256", material)
357	      .update(normalizeEmailForBlindIndex(email), "utf8")
358	      .digest();
359	  } finally {
360	    material.fill(0);
361	  }
362	}
