366	export interface Argon2idParameters {
367	  readonly memoryCostKiB: number;
368	  readonly timeCost: number;
369	  readonly parallelism: number;
370	  readonly hashLength: number;
371	}
372	
373	export interface AuditSourceIpKdfParameters {
374	  readonly algorithm: "argon2id";
375	  readonly memoryCostKiB: number;
376	  readonly iterations: number;
377	  readonly parallelism: number;
378	  readonly hashLength: 32;
379	}
380	
381	const AUDIT_SOURCE_IP_KDF_DOMAIN = "debateai:audit-source-ip:v1\0";
382	const AUDIT_USER_AGENT_KDF_DOMAIN = "debateai:audit-user-agent:v1\0";
383	
384	/**
385	 * The off-thread Argon2 surface. `Argon2WorkerPool` satisfies it structurally;
386	 * tests inject deterministic fakes. Nothing in this module may compute Argon2
387	 * itself.
388	 */
389	export interface Argon2Executor {
390	  hashPassword(
391	    password: Uint8Array,
392	    salt: Uint8Array,
393	    parameters: Argon2PasswordParameters
394	  ): Promise<string>;
395	  verifyPassword(password: Uint8Array, encodedHash: string): Promise<boolean>;
396	  hashAuditContext(
397	    value: Uint8Array,
398	    salt: Uint8Array,
399	    parameters: Argon2AuditParameters
400	  ): Promise<string>;
401	}
402	
403	/**
404	 * UTF-8 bytes in a freshly allocated, exactly-sized ArrayBuffer.
405	 *
406	 * `Buffer.from(string)` would draw from Node's shared allocation pool, and the
407	 * pool transfers these buffers to the worker thread — detaching a shared pool
408	 * buffer would corrupt unrelated live Buffers. TextEncoder always allocates its
409	 * own exact-size buffer.
410	 *
411	 * hash-wasm hashes a Uint8Array password exactly as it hashes the equivalent
412	 * UTF-8 string, so moving to byte transfer leaves every digest byte-identical.
413	 */
414	function utf8Bytes(value: string): Uint8Array {
415	  return new TextEncoder().encode(value);
416	}
417	
418	/** A detachable, zeroable copy, so the caller's long-lived salt is never transferred. */
419	function copyBytes(value: Uint8Array): Uint8Array {
420	  return new Uint8Array(value);
421	}
422	
423	function validateAuditKdfParameters(
424	  value: string,
425	  salt: Uint8Array,
426	  parameters: AuditSourceIpKdfParameters
427	): void {
428	  if (value.length === 0 || salt.byteLength < 32 || parameters.algorithm !== "argon2id"
429	    || !Number.isInteger(parameters.memoryCostKiB) || parameters.memoryCostKiB < 19_456
430	    || !Number.isInteger(parameters.iterations) || parameters.iterations < 2
431	    || !Number.isInteger(parameters.parallelism) || parameters.parallelism < 1
432	    || parameters.hashLength !== 32) {
433	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
434	  }
435	}
436	
437	async function hashAuditContextValue(
438	  executor: Argon2Executor,
439	  value: string,
440	  salt: Uint8Array,
441	  parameters: AuditSourceIpKdfParameters,
442	  domain: string
443	): Promise<string> {
444	  validateAuditKdfParameters(value, salt, parameters);
445	  return executor.hashAuditContext(utf8Bytes(`${domain}${value}`), copyBytes(salt), {
446	    memoryCostKiB: parameters.memoryCostKiB,
447	    iterations: parameters.iterations,
448	    parallelism: parameters.parallelism,
449	    hashLength: parameters.hashLength
450	  });
451	}
452	
453	export async function hashAuditSourceIp(
454	  executor: Argon2Executor,
455	  sourceIp: string,
456	  salt: Uint8Array,
457	  parameters: AuditSourceIpKdfParameters
458	): Promise<string> {
459	  return hashAuditContextValue(executor, sourceIp, salt, parameters, AUDIT_SOURCE_IP_KDF_DOMAIN);
460	}
461	
462	export async function hashAuditUserAgent(
463	  executor: Argon2Executor,
464	  userAgent: string,
465	  salt: Uint8Array,
466	  parameters: AuditSourceIpKdfParameters
467	): Promise<string> {
468	  return hashAuditContextValue(executor, userAgent, salt, parameters, AUDIT_USER_AGENT_KDF_DOMAIN);
469	}
470	
471	export async function hashPassword(
472	  executor: Argon2Executor,
473	  password: string,
474	  parameters: Argon2idParameters
475	): Promise<string> {
476	  if (typeof password !== "string" || password.length === 0
477	    || !Number.isInteger(parameters.memoryCostKiB) || parameters.memoryCostKiB < 19_456
478	    || !Number.isInteger(parameters.timeCost) || parameters.timeCost < 2
479	    || !Number.isInteger(parameters.parallelism) || parameters.parallelism < 1
480	    || !Number.isInteger(parameters.hashLength) || parameters.hashLength < 32) {
481	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
482	  }
483	  const salt = new Uint8Array(16);
484	  randomFillSync(salt);
485	  return executor.hashPassword(utf8Bytes(password), salt, {
486	    memoryCostKiB: parameters.memoryCostKiB,
487	    timeCost: parameters.timeCost,
488	    parallelism: parameters.parallelism,
489	    hashLength: parameters.hashLength
490	  });
491	}
492	
493	/**
494	 * A wrong password, or an encoded hash Argon2 cannot parse, is `false` — the
495	 * pre-existing contract. Infrastructure failure (worker crash, timeout,
496	 * capacity exhaustion, closed pool) propagates as a typed rejection and is
497	 * never converted into `false`.
498	 */
499	export async function verifyPassword(
500	  executor: Argon2Executor,
501	  encodedHash: string,
502	  password: string
503	): Promise<boolean> {
504	  if (!encodedHash.startsWith("$argon2id$")) return false;
505	  return executor.verifyPassword(utf8Bytes(password), encodedHash);
506	}
507	
508	/**
509	 * PROVISIONAL cache bounds, pending V ratification against measured evidence.
510	 */
511	export const AUDIT_SOURCE_IP_CACHE_BOUNDS = Object.freeze({
512	  capacity: 4_096,
513	  ttlMs: 60_000
514	});
515	
516	const AUDIT_SOURCE_IP_CACHE_DOMAIN = "debateai:audit-source-ip-cache:v1";
517	
518	interface AuditIpCacheEntry {
519	  digest: string | undefined;
520	  promise: Promise<string> | undefined;
521	  /** Absolute; set once at insertion and never extended by a hit. */
522	  readonly expiresAt: number;
523	  lastUsedAt: number;
524	}
525	
526	export interface AuditContextHasherOptions {
527	  readonly capacity?: number;
528	  readonly ttlMs?: number;
529	  readonly now?: () => number;
530	}
531	
532	/**
533	 * Owns the audit-context derivations for ONE salt/parameter epoch, plus the
534	 * ticket-authorized bounded per-IP cache.
535	 *
536	 * Privacy contract: only the normalized source IP derivation is cached. User
537	 * agents use the worker but are never cached — T1 authorizes a per-IP cache,
538	 * not broader retained UA state. Passwords, password verification, tokens,
539	 * email, request IDs and raw IP values are never cached.
540	 *
541	 * The map key is an HMAC under a fresh random process-local key over a
542	 * domain-separated canonical input that binds the normalized IP, a salt
543	 * fingerprint and the full KDF parameter tuple. It is a locator only and is
544	 * never persisted as the audit digest; a salt, parameter or domain change
545	 * necessarily misses, preserving VR-7 domain separation and rotation.
546	 */
547	export class AuditContextHasher {
548	  private readonly executor: Argon2Executor;
549	  private readonly salt: Buffer;
550	  private readonly parameters: AuditSourceIpKdfParameters;
551	  private readonly capacity: number;
552	  private readonly ttlMs: number;
553	  private readonly now: () => number;
554	  private readonly cacheKey: Buffer;
555	  private readonly saltFingerprint: string;
556	  private readonly entries = new Map<string, AuditIpCacheEntry>();
557	  private closed = false;
558	
559	  constructor(
560	    executor: Argon2Executor,
561	    salt: Uint8Array,
562	    parameters: AuditSourceIpKdfParameters,
563	    options: AuditContextHasherOptions = {}
564	  ) {
565	    if (salt.byteLength < 32) throw new CryptoInputError("CRYPTO_KEY_INVALID");
566	    this.executor = executor;
567	    this.salt = Buffer.from(salt);
568	    this.parameters = Object.freeze({ ...parameters });
569	    this.capacity = options.capacity ?? AUDIT_SOURCE_IP_CACHE_BOUNDS.capacity;
570	    this.ttlMs = options.ttlMs ?? AUDIT_SOURCE_IP_CACHE_BOUNDS.ttlMs;
571	    this.now = options.now ?? Date.now;
572	    this.cacheKey = randomBytes(32);
573	    this.saltFingerprint = createHash("sha256").update(this.salt).digest("hex");
574	  }
575	
576	  /** Opaque keyed locator. Never plaintext, never an unkeyed digest. */
577	  private locator(normalizedIp: string): string {
578	    const canonical = JSON.stringify([
579	      AUDIT_SOURCE_IP_CACHE_DOMAIN,
580	      AUDIT_SOURCE_IP_KDF_DOMAIN,
581	      normalizedIp,
582	      this.saltFingerprint,
583	      this.parameters.algorithm,
584	      this.parameters.memoryCostKiB,
585	      this.parameters.iterations,
586	      this.parameters.parallelism,
587	      this.parameters.hashLength
588	    ]);
589	    return createHmac("sha256", this.cacheKey).update(canonical, "utf8").digest("hex");
590	  }
591	
592	  /** Lazy, timer-free reclamation: expired first, then settled LRU. */
593	  private reclaim(): void {
594	    const now = this.now();
595	    for (const [key, entry] of this.entries) {
596	      if (entry.expiresAt <= now) this.entries.delete(key);
597	    }
598	    while (this.entries.size >= this.capacity) {
599	      let oldestKey: string | undefined;
600	      let oldestAt = Number.POSITIVE_INFINITY;
601	      for (const [key, entry] of this.entries) {
602	        // In-flight entries are never evicted: they are the coalescing point
603	        // for their own awaiters.
604	        if (entry.digest === undefined) continue;
605	        if (entry.lastUsedAt < oldestAt) {
606	          oldestAt = entry.lastUsedAt;
607	          oldestKey = key;
608	        }
609	      }
610	      if (oldestKey === undefined) return;
611	      this.entries.delete(oldestKey);
612	    }
613	  }
614	
615	  async hashSourceIp(normalizedIp: string): Promise<string> {
616	    if (this.closed) throw new CryptoInputError("CRYPTO_KEY_INVALID");
617	    validateAuditKdfParameters(normalizedIp, this.salt, this.parameters);
618	    const key = this.locator(normalizedIp);
619	    const now = this.now();
620	    const existing = this.entries.get(key);
621	    if (existing !== undefined) {
622	      if (existing.expiresAt > now) {
623	        if (existing.digest !== undefined) {
624	          existing.lastUsedAt = now;
625	          // Byte-identical to a miss: the same Argon2 digest string.
626	          return existing.digest;
627	        }
628	        if (existing.promise !== undefined) return existing.promise;
629	      }
630	      this.entries.delete(key);
631	    }
632	
633	    const promise = hashAuditContextValue(
634	      this.executor, normalizedIp, this.salt, this.parameters, AUDIT_SOURCE_IP_KDF_DOMAIN
635	    );
636	
637	    this.reclaim();
638	    if (this.entries.size >= this.capacity) {
639	      // Capacity is entirely in-flight. Bypass insertion rather than exceed the
640	      // cap; the derivation still runs and still returns a correct digest.
641	      return promise;
642	    }
643	    const entry: AuditIpCacheEntry = {
644	      digest: undefined,
645	      promise,
646	      expiresAt: now + this.ttlMs,
647	      lastUsedAt: now
648	    };
649	    this.entries.set(key, entry);
650	    // In-flight entries count toward the cap from this moment.
651	    return promise.then((digest) => {
652	      if (this.entries.get(key) === entry) {
653	        entry.digest = digest;
654	        entry.promise = undefined;
655	        entry.lastUsedAt = this.now();
656	      }
657	      return digest;
658	    }, (error: unknown) => {
659	      // Never cache an error, and never leave a rejected in-flight entry
660	      // occupying capacity or coalescing later callers onto a failure.
661	      if (this.entries.get(key) === entry) this.entries.delete(key);
662	      throw error;
663	    });
664	  }
665	
666	  /** Worker-backed but deliberately uncached. */
667	  async hashUserAgent(normalizedUserAgent: string): Promise<string> {
668	    if (this.closed) throw new CryptoInputError("CRYPTO_KEY_INVALID");
669	    return hashAuditContextValue(
670	      this.executor, normalizedUserAgent, this.salt, this.parameters, AUDIT_USER_AGENT_KDF_DOMAIN
671	    );
672	  }
673	
674	  cacheSize(): number {
675	    return this.entries.size;
676	  }
677	
678	  /** Idempotent. Clears cached entries and zeroes the HMAC key and salt copy. */
679	  close(): void {
680	    if (this.closed) return;
681	    this.closed = true;
682	    this.entries.clear();
683	    this.cacheKey.fill(0);
684	    this.salt.fill(0);
685	  }
686	}
687	
688	export function generateVerificationToken(): string {
689	  return randomBytes(32).toString("base64url");
690	}
691	
692	export function hashVerificationToken(token: string): string {
693	  if (typeof token !== "string" || token.length < 32) {
694	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
695	  }
696	  return `sha256:${createHash("sha256").update(token, "utf8").digest("hex")}`;
697	}
698	
699	const PSEUDONYM_ADJECTIVES = Object.freeze([
700	  "amber", "brisk", "calm", "clear", "cobalt", "coral", "crisp", "daring",
701	  "ember", "gentle", "golden", "honest", "indigo", "lucid", "mellow", "nimble",
702	  "open", "patient", "quiet", "rapid", "silver", "steady", "verdant", "vivid"
703	]);
704	const PSEUDONYM_NOUNS = Object.freeze([
705	  "badger", "cedar", "comet", "dolphin", "falcon", "forest", "harbor", "heron",
706	  "island", "lantern", "maple", "meadow", "otter", "pebble", "quartz", "raven",
707	  "river", "sparrow", "summit", "thistle", "tiger", "willow", "wren", "zephyr"
708	]);
709	
710	export function generatePseudonym(): string {
711	  const adjective = PSEUDONYM_ADJECTIVES[randomInt(PSEUDONYM_ADJECTIVES.length)]!;
712	  const noun = PSEUDONYM_NOUNS[randomInt(PSEUDONYM_NOUNS.length)]!;
713	  return `${adjective}-${noun}-${randomBytes(3).toString("hex")}`;
714	}
715	
716	export interface UserDekStore {
717	  store(userId: string, dek: Uint8Array): Promise<void>;
718	}
719	
720	export class FileUserDekStore implements UserDekStore {
721	  constructor(
722	    private readonly root: string,
723	    private readonly kek: KekHandle
724	  ) {
725	    if (root.trim() === "") throw new TypeError("USER_DEK_STORE_PATH_REQUIRED");
726	  }
727	
728	  async store(userId: string, dek: Uint8Array): Promise<void> {
729	    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId)) {
730	      throw new TypeError("USER_DEK_STORE_USER_ID_INVALID");
731	    }
732	    const aad = [
733	      "secret-store", "user-dek", userId, "run:none", userId,
734	      `user-dek:${userId}`, "1"
735	    ] as const;
736	    const envelope = wrapDek(this.kek, dek, aad);
737	    const users = join(this.root, "users");
738	    const directory = join(users, userId);
739	    await mkdir(this.root, { recursive: true, mode: 0o700 });
740	    await chmod(this.root, 0o700);
741	    await mkdir(users, { recursive: true, mode: 0o700 });
742	    await chmod(users, 0o700);
743	    await mkdir(directory, { recursive: false, mode: 0o700 });
744	    const location = join(directory, "dek.v1.json");
745	    const file = await open(location, "wx", 0o600);
746	    try {
747	      await file.writeFile(JSON.stringify({
748	        version: 1,
749	        user_id: userId,
750	        key_id: envelope.keyId,
751	        wrapped_dek: envelope
752	      }), "utf8");
753	    } finally {
754	      await file.close();
755	    }
756	  }
757	}
