          });
          return;
        }
        const deliveryRecord = await this.attemptVerificationDelivery(delivery!);
        delivery = undefined;
        await releaseReservation();
        await this.recordVerificationDelivery(deliveryRecord);
      })
      .catch(() => {
        if (duplicate === undefined) {
