24	interface FakeWorker extends Argon2WorkerHandle {
25	  readonly received: { id: string; op: string }[];
26	  emitReady(): void;
27	  settle(id: string, digest: string): void;
28	  verified(id: string, matches: boolean): void;
29	  fail(id: string): void;
30	  crash(): void;
31	  readonly terminated: () => number;
32	  readonly refCount: () => number;
