35	function createFakeWorker(index: number, autoReady = true): FakeWorker {
36	  const listeners = new Map<string, ((value: never) => void)[]>();
37	  const received: { id: string; op: string }[] = [];
38	  let terminateCalls = 0;
39	  let refs = 0;
40	  const emit = (event: string, value: unknown): void => {
41	    for (const listener of listeners.get(event) ?? []) (listener as (v: unknown) => void)(value);
42	  };
43	  const worker: FakeWorker = {
44	    threadId: 100 + index,
45	    received,
46	    postMessage(message: unknown) {
47	      const request = message as { id: string; op: string };
48	      received.push({ id: request.id, op: request.op });
49	    },
50	    on(event: string, listener: (value: never) => void) {
51	      const bucket = listeners.get(event) ?? [];
52	      bucket.push(listener);
53	      listeners.set(event, bucket);
54	    },
55	    async terminate() {
56	      terminateCalls += 1;
57	      return 0;
58	    },
59	    ref() { refs += 1; },
60	    unref() { refs -= 1; },
61	    emitReady() { emit("message", { kind: "ready" }); },
62	    settle(id: string, digest: string) { emit("message", { kind: "result", id, digest }); },
63	    verified(id: string, matches: boolean) { emit("message", { kind: "verified", id, matches }); },
64	    fail(id: string) {
65	      emit("message", { kind: "failed", id, code: "ARGON2_WORKER_JOB_FAILED" });
66	    },
67	    crash() { emit("error", new Error("worker died")); },
68	    terminated: () => terminateCalls,
69	    refCount: () => refs
70	  } as FakeWorker;
71	  if (autoReady) queueMicrotask(() => worker.emitReady());
72	  return worker;
73	}
