79	async function settled<T>(promise: Promise<T>): Promise<"pending" | "resolved" | "rejected"> {
80	  let state: "pending" | "resolved" | "rejected" = "pending";
81	  promise.then(() => { state = "resolved"; }, () => { state = "rejected"; });
82	  await new Promise((resolve) => setImmediate(resolve));
83	  return state;
84	}
