458	function countingExecutor(): Argon2Executor & {
459	  readonly calls: { domainAndValue: string }[];
460	  release(): void;
461	  failNext(): void;
462	} {
463	  const calls: { domainAndValue: string }[] = [];
464	  let gate: (() => void) | undefined;
465	  let pending: Promise<void> | undefined;
466	  let shouldFail = false;
467	  return {
468	    calls,
469	    release() { gate?.(); gate = undefined; pending = undefined; },
470	    failNext() { shouldFail = true; },
471	    async hashPassword() { throw new Error("unused"); },
472	    async verifyPassword() { throw new Error("unused"); },
473	    async hashAuditContext(value: Uint8Array): Promise<string> {
474	      const decoded = new TextDecoder().decode(value);
475	      calls.push({ domainAndValue: decoded });
476	      if (pending !== undefined) await pending;
477	      if (shouldFail) {
478	        shouldFail = false;
479	        throw new Argon2InfrastructureError("ARGON2_WORKER_FAILED");
480	      }
481	      // Deterministic and unique per (domain+value) so equality proves identity.
482	      return Buffer.from(decoded).toString("hex").padEnd(64, "0").slice(0, 64);
483	    }
484	  } as Argon2Executor & { calls: { domainAndValue: string }[]; release(): void; failNext(): void };
485	}
