  version: 19,
  minMemoryCostKiB: 19_456,
  maxMemoryCostKiB: 262_144,
  minTimeCost: 2,
  maxTimeCost: 10,
  minParallelism: 1,
  maxParallelism: 4,
  minSaltBytes: 16,
  maxSaltBytes: 64,
  minHashBytes: 32,
