    return frame.kind === "verified" && typeof frame.matches === "boolean"
      ? { kind: "verified", matches: frame.matches }
      : { kind: "fault" };
  }
  if (frame.kind !== "result" || typeof frame.digest !== "string") return { kind: "fault" };
