          correlationId,
          occurredAt: requestedAt,
          source
        }).catch(() => {
          console.error(
            `[AUTH_REGISTRATION_FAILURE_AUDIT_FAILED] correlation=${correlationId} code=AUDIT_RECORD_FAILED`
