          releaseMailDispatch = undefined;
          this.dispatchVerification(pendingDelivery, release);
        }
        if (releaseMailDispatch !== undefined) {
          this.dispatchMailReservationHold(releaseMailDispatch, true);
        }
      }
    }
  }
}

