const out: Record<string, unknown> = {};
const flush = async (n = 6) => { for (let i = 0; i < n; i += 1) await new Promise((r) => setImmediate(r)); };
function counting(): Argon2Executor & { calls: string[] } {
  const calls: string[] = [];
  return {
    calls,
    async hashPassword() { return "$argon2id$x"; },
    async verifyPassword() { return false; },
    async hashAuditContext(value: Uint8Array) {
      const d = new TextDecoder().decode(value); calls.push(d);
      return Buffer.from(d).toString("hex").padEnd(64, "0").slice(0, 64);
    }
  } as Argon2Executor & { calls: string[] };
}

// P2-A(1): the production clock is monotonic, not wall-clock.
{
  const h = new AuditContextHasher(counting(), SALT, auditKdf);
  const clock = (h as unknown as { now: () => number }).now;
  out.p2a_productionClockIsDateNow = clock === Date.now;
  const a = clock(); const b = clock();
  out.p2a_productionClockIsMonotonicNonDecreasing = b >= a;
  out.p2a_productionClockDiffersFromWallClock = Math.abs(clock() - Date.now()) > 1_000_000;
  out.PASS_ttlUsesMonotonicClock = clock !== Date.now && out.p2a_productionClockDiffersFromWallClock === true;
  h.close();
}
// P2-A(2): same-tick LRU is deterministic.
{
  const ex = counting();
  const h = new AuditContextHasher(ex, SALT, auditKdf, {
    capacity: 3, ttlMs: 10_000_000, now: () => 5_000
  });
  await h.hashSourceIp("ip-a"); await h.hashSourceIp("ip-b"); await h.hashSourceIp("ip-c");
  await h.hashSourceIp("ip-a");
  const before = ex.calls.length;
  await h.hashSourceIp("ip-d");
  await h.hashSourceIp("ip-a");
  out.p2a_sameTick_extraDerivationsForA = ex.calls.length - before - 1;
  await h.hashSourceIp("ip-b");
  out.p2a_sameTick_bWasTheVictim = ex.calls.length - before - 1 === 1;
  out.PASS_sameTickLruEvictsTrueLru =
    (out.p2a_sameTick_extraDerivationsForA as number) === 0 && out.p2a_sameTick_bWasTheVictim === true;
  out.p2a_sameTick_cacheSize = h.cacheSize();
  h.close();
}
// P1-D: operation-bound protocol validation.
{
  function fake(index: number) {
    const listeners = new Map<string, ((v: never) => void)[]>();
    const emit = (e: string, v: unknown) => {
      for (const l of listeners.get(e) ?? []) (l as (x: unknown) => void)(v);
    };
    const received: { id: string; op: string }[] = [];
    const w = {
      threadId: 100 + index, received,
      postMessage(m: unknown) { received.push(m as { id: string; op: string }); },
      on(e: string, l: (v: never) => void) { const b = listeners.get(e) ?? []; b.push(l); listeners.set(e, b); },
      async terminate() { return 0; }, ref() {}, unref() {},
      reply(v: unknown) { emit("message", v); }
    };
    queueMicrotask(() => emit("message", { kind: "ready" }));
    return w as unknown as Argon2WorkerHandle & {
      received: { id: string; op: string }[]; reply(v: unknown): void;
    };
  }
  const mutants: { label: string; frame: (id: string) => unknown; op: "hash" | "verify" | "audit" }[] = [
    { label: "arbitrary string as password hash", op: "hash", frame: (id) => ({ kind: "result", id, digest: "pwned" }) },
    { label: "empty digest", op: "hash", frame: (id) => ({ kind: "result", id, digest: "" }) },
    { label: "out-of-envelope encoded hash", op: "hash",
      frame: (id) => ({ kind: "result", id, digest: "$argon2id$v=19$m=2097152,t=3,p=1$" + "A".repeat(22) + "$" + "A".repeat(43) }) },
    { label: "wrong-operation verified frame for a hash job", op: "hash", frame: (id) => ({ kind: "verified", id, matches: true }) },
    { label: "non-hex audit digest", op: "audit", frame: (id) => ({ kind: "result", id, digest: "not-a-digest" }) },
    { label: "short hex audit digest", op: "audit", frame: (id) => ({ kind: "result", id, digest: "ab".repeat(16) }) },
    { label: "wrong-operation result frame for a verify job", op: "verify", frame: (id) => ({ kind: "result", id, digest: "$argon2id$v=19$m=65536,t=3,p=1$" + "A".repeat(22) + "$" + "A".repeat(43) }) },
    { label: "non-boolean matches", op: "verify", frame: (id) => ({ kind: "verified", id, matches: "true" }) },
    { label: "unsolicited frame for an unknown id", op: "hash", frame: () => ({ kind: "result", id: "deadbeef", digest: "x" }) }
  ];
  const results: Record<string, unknown> = {};
  for (const mutant of mutants) {
    const workers: (Argon2WorkerHandle & { received: { id: string; op: string }[]; reply(v: unknown): void })[] = [];
    const pool = new Argon2WorkerPool({
      workers: 1, closeDrainMs: 20, spawn: (i) => { const w = fake(i); workers.push(w); return w; }
    });
    await pool.ready();
    const job = mutant.op === "hash"
      ? pool.hashPassword(new Uint8Array(8), new Uint8Array(16),
        { memoryCostKiB: 65_536, timeCost: 3, parallelism: 1, hashLength: 32 })
      : mutant.op === "audit"
        ? pool.hashAuditContext(new Uint8Array(8), new Uint8Array(32),
          { memoryCostKiB: 19_456, iterations: 2, parallelism: 1, hashLength: 32 })
        : pool.verifyPassword(new Uint8Array(8),
          "$argon2id$v=19$m=65536,t=3,p=1$" + "A".repeat(22) + "$" + "A".repeat(43));
    const settled = job.then((v) => ({ settled: "resolved", value: v }),
      (e: unknown) => ({ settled: "rejected", code: (e as { code?: string }).code }));
    await flush();
    workers[0]!.reply(mutant.frame(workers[0]!.received[0]!.id));
    const outcome = await settled;
    results[mutant.label] = { ...outcome, workerReplaced: workers.length > 1 };
    await pool.close();
  }
  out.p1d_mutants = results;
  out.PASS_everyProtocolMutantRejectedAndWorkerLost = Object.values(results).every((r) =>
    (r as { settled: string; code?: string; workerReplaced: boolean }).settled === "rejected"
    && (r as { code?: string }).code === "ARGON2_WORKER_FAILED"
    && (r as { workerReplaced: boolean }).workerReplaced === true);

  // A LAWFUL frame for each operation must still be accepted.
  const workers: (Argon2WorkerHandle & { received: { id: string; op: string }[]; reply(v: unknown): void })[] = [];
  const pool = new Argon2WorkerPool({
    workers: 1, closeDrainMs: 20, spawn: (i) => { const w = fake(i); workers.push(w); return w; }
  });
  await pool.ready();
  const good = "$argon2id$v=19$m=65536,t=3,p=1$" + "A".repeat(22) + "$" + "A".repeat(43);
  const h = pool.hashPassword(new Uint8Array(8), new Uint8Array(16),
    { memoryCostKiB: 65_536, timeCost: 3, parallelism: 1, hashLength: 32 });
  await flush(); workers[0]!.reply({ kind: "result", id: workers[0]!.received[0]!.id, digest: good });
  out.p1d_lawfulHash = await h === good;
  const a = pool.hashAuditContext(new Uint8Array(8), new Uint8Array(32),
    { memoryCostKiB: 19_456, iterations: 2, parallelism: 1, hashLength: 32 });
  await flush(); workers[0]!.reply({ kind: "result", id: workers[0]!.received[1]!.id, digest: "ab".repeat(32) });
  out.p1d_lawfulAudit = await a === "ab".repeat(32);
  const v = pool.verifyPassword(new Uint8Array(8), good);
  await flush(); workers[0]!.reply({ kind: "verified", id: workers[0]!.received[2]!.id, matches: true });
  out.p1d_lawfulVerify = await v === true;
  out.p1d_noSpuriousReplacement = workers.length === 1;
  await pool.close();
}
clearInterval(keepAlive);
console.log(JSON.stringify(out, null, 2));
EOF
